import { LOGO_ART, LOGO_BG } from './logoArt'

/** Antresol app mark «Дом»: a glass house with a play inside on the violet tile. Same artwork as the PWA icon
 *  (generated by docs/identity/make-icon.py). */
export function LogoMark({ size = 28 }: { size?: number }) {
  return (
    <svg width={size} height={size} viewBox="0 0 1024 1024" aria-hidden focusable="false">
      <defs dangerouslySetInnerHTML={{ __html: LOGO_BG }} />
      <rect width="1024" height="1024" rx="228" fill="url(#lm-bg)" />
      <g dangerouslySetInnerHTML={{ __html: LOGO_ART }} />
    </svg>
  )
}
